INSERT INTO activite (slug,titre,categorie,ville,lieu,organisateur_nom,prix,image,debut,description,badge,duree,capacite,places_disponibles,public_cible,rendez_vous,programme,inclus,preparation,demonstration,publiee) VALUES
('chocolat','Atelier Maître Chocolatier & Création de Pralines','gastronomie','Bruxelles','Sablon, Bruxelles','Atelier Saint-Géry',45,'chocolat','2026-10-24T14:00:00+02:00','Découvrez les gestes du chocolatier et confectionnez vos propres pralines dans un atelier convivial au cœur de Bruxelles.','À découvrir','3 heures',12,4,'À partir de 14 ans · Débutants bienvenus','Quartier du Sablon, Bruxelles',ARRAY['Découvrir les origines du cacao et le métier de chocolatier.','S’initier au tempérage et au moulage du chocolat.','Confectionner ses pralines et échanger autour d’une dégustation.']::text[],ARRAY['Matériel de l’atelier','Ingrédients pour les pralines','Accompagnement pendant l’atelier']::text[],'Prévoyez des chaussures fermées et signalez vos allergies alimentaires à l’organisateur avant toute inscription.',true,true),
('randonnee','Randonnée au crépuscule dans les Hautes Fagnes','nature','Malmedy','Malmedy, Ardennes','Sentiers d’Ardenne',12,'randonnee','2026-10-25T16:00:00+01:00','Parcourez les passerelles des Hautes Fagnes et partagez un moment en pleine nature à la lumière du soir.','Au grand air','2 h 30',16,6,'Adultes · Marche sur sentiers','Malmedy, aux portes des Hautes Fagnes',ARRAY['Faire connaissance avec le groupe et découvrir le parcours.','Explorer les paysages des Hautes Fagnes à pied.','Profiter d’une pause pour observer la nature au crépuscule.']::text[],ARRAY['Balade accompagnée','Présentation des paysages locaux']::text[],'Prévoyez des chaussures de marche, de l’eau et des vêtements adaptés à la météo.',true,true),
('ceramique','Initiation au Tournage Céramique & Poterie','art','Bruxelles','Saint-Gilles, Bruxelles','Studio Argile & Feu',55,'ceramique','2026-10-24T10:00:00+02:00','Prenez le temps de créer. Une découverte du tour de potier, de la terre et des premières formes, accessible aux débutants.',NULL,'2 heures',8,3,'Adultes · Débutants bienvenus','Studio de céramique, Saint-Gilles',ARRAY['Découvrir la terre et les outils du potier.','Apprendre à centrer la terre sur le tour.','Réaliser une première forme et échanger sur les créations.']::text[],ARRAY['Terre et outils','Utilisation du tour','Accompagnement de l’atelier']::text[],'Portez une tenue qui peut se salir. Les modalités de cuisson et de récupération des pièces seront précisées par l’organisateur.',true,true),
('brasserie','Visite & Dégustation en Microbrasserie Artisanale','gastronomie','Liège','Centre-ville, Liège','Brasserie Curtius & Co',20,'brasserie','2026-10-25T15:00:00+01:00','Rencontrez des artisans passionnés et découvrez les étapes du brassage lors d’une visite de leur atelier.',NULL,'1 h 30',12,0,'Adultes uniquement','Centre-ville de Liège',ARRAY['Rencontrer l’équipe de la microbrasserie.','Découvrir les ingrédients et les étapes du brassage.','Échanger avec les artisans autour de leurs savoir-faire.']::text[],ARRAY['Visite accompagnée','Présentation du processus de fabrication']::text[],'Les détails de la dégustation seront précisés par l’organisateur.',true,true),
('street-art','Fresque participative & Visite Street Art Urbain','art','Charleroi','Centre, Charleroi','Collectif Métropole',0,'street-art','2026-10-24T11:00:00+02:00','Explorez les fresques du quartier et participez à une création collective avec des artistes locaux.',NULL,'2 heures',20,8,'Tout public · Mineurs accompagnés','Centre de Charleroi',ARRAY['Découvrir les fresques du quartier.','Rencontrer le collectif et ses inspirations.','Participer à un moment de création partagé.']::text[],ARRAY['Parcours accompagné','Présentation des œuvres']::text[],'Prévoyez une tenue confortable et adaptée à une activité en extérieur.',true,true),
('balade','Clean-up & Balade Botanique le long de la Meuse','nature','Namur','Citadelle, Namur','Namur en Transition',0,'balade','2026-10-25T09:30:00+01:00','Une balade pour découvrir les plantes des berges de la Meuse et prendre soin ensemble de notre environnement.',NULL,'2 heures',20,9,'Tout public · Mineurs accompagnés','Berges de la Meuse, au pied de la citadelle de Namur',ARRAY['Découvrir les plantes présentes le long de la Meuse.','Participer à un nettoyage collectif des berges.','Partager les découvertes de la matinée avec le groupe.']::text[],ARRAY['Balade accompagnée','Présentation de la flore locale']::text[],'Apportez des gants, des chaussures adaptées et une gourde.',true,true),
('cinema','Ciné-débat : la transition écologique au quotidien','culture','Bruxelles','Flagey, Ixelles','Mundo Madou',0,'cinema','2026-10-28T19:00:00+01:00','Une projection suivie d’un échange ouvert autour des initiatives locales et des gestes du quotidien.',NULL,'2 h 30',40,15,'Adultes et adolescents accompagnés','Quartier Flagey, Ixelles',ARRAY['Accueillir les participants et présenter le sujet.','Assister à la projection du documentaire.','Échanger sur les initiatives locales et les gestes du quotidien.']::text[],ARRAY['Projection','Échange après le film']::text[],'Prévoyez d’arriver quelques minutes avant la séance. Le programme précis sera confirmé par l’organisateur.',true,true)
